  if (!plain(state) || !exact(state, ['entries']) || !Array.isArray(state.entries) || state.entries.some((entry) => !validEntry(entry))) {
    throw new TypeError('invalid state');
  }
  if (new Set(state.entries.map((entry) => entry.id)).size !== state.entries.length) throw new TypeError('duplicate state id');
  if (!plain(command) || !plain(command.actor) || !exact(command.actor, ['id', 'role']) ||
      typeof command.actor.id !== 'string' || command.actor.id.length === 0 ||
      !['viewer', 'editor'].includes(command.actor.role)) throw new TypeError('invalid actor');
  if (!command.actor.role) throw new Error('Forbidden');

  const entries = state.entries.map((entry) => ({ ...entry }));
  if (command.type === 'ADD') {
    if (!exact(command, ['type', 'actor', 'entry']) || !validEntry(command.entry)) throw new TypeError('invalid ADD');
    if (entries.some((entry) => entry.id === command.entry.id)) throw new Error('Duplicate id');
    return { entries: entries.concat({ ...command.entry }) };
