'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['applyCatalogCommand', 'createCatalogState']);
const { createCatalogState, applyCatalogCommand } = api;
const typeError = fn => assert.throws(fn, TypeError);
const editor = { id: 'e1', role: 'editor' };
const viewer = { id: 'v1', role: 'viewer' };

const initial = createCatalogState();
assert.deepStrictEqual(initial, { entries: [] });
assert.notStrictEqual(createCatalogState(), initial);
const entry = { id: 'a', title: 'Alpha', quantity: 0 };
const added = applyCatalogCommand(initial, { type: 'ADD', actor: editor, entry });
assert.deepStrictEqual(added, { entries: [{ id: 'a', title: 'Alpha', quantity: 0 }] });
assert.deepStrictEqual(initial, { entries: [] });
assert.notStrictEqual(added.entries[0], entry);
entry.title = 'changed';
assert.strictEqual(added.entries[0].title, 'Alpha');
const two = applyCatalogCommand(added, { type: 'ADD', actor: editor, entry: { id: 'b', title: 'Beta', quantity: 2 } });
assert.notStrictEqual(two.entries[0], added.entries[0]);
const changes = { title: 'Alpha 2', quantity: 3 };
const changed = applyCatalogCommand(two, { type: 'CHANGE', actor: editor, id: 'a', changes });
assert.deepStrictEqual(changed.entries, [{ id: 'a', title: 'Alpha 2', quantity: 3 }, { id: 'b', title: 'Beta', quantity: 2 }]);
assert.notStrictEqual(changed.entries[1], two.entries[1]);
changes.title = 'bad';
assert.strictEqual(changed.entries[0].title, 'Alpha 2');
const removed = applyCatalogCommand(changed, { type: 'REMOVE', actor: editor, id: 'a' });
assert.deepStrictEqual(removed.entries, [{ id: 'b', title: 'Beta', quantity: 2 }]);
assert.notStrictEqual(removed.entries[0], changed.entries[1]);

assert.throws(() => applyCatalogCommand(changed, { type: 'ADD', actor: viewer, entry: { id: 'c', title: 'C', quantity: 1 } }), err => err.message === 'Forbidden');
assert.throws(() => applyCatalogCommand(changed, { type: 'ADD', actor: editor, entry: { id: 'a', title: 'Again', quantity: 1 } }), err => err.message === 'Duplicate id');
assert.throws(() => applyCatalogCommand(changed, { type: 'CHANGE', actor: editor, id: 'missing', changes: { title: 'X' } }), err => err.message === 'Entry not found');
assert.throws(() => applyCatalogCommand(changed, { type: 'REMOVE', actor: editor, id: 'missing' }), err => err.message === 'Entry not found');
assert.deepStrictEqual(changed.entries, [{ id: 'a', title: 'Alpha 2', quantity: 3 }, { id: 'b', title: 'Beta', quantity: 2 }]);

typeError(() => applyCatalogCommand(null, { type: 'REMOVE', actor: editor, id: 'a' }));
typeError(() => applyCatalogCommand({ entries: [], extra: 1 }, { type: 'REMOVE', actor: editor, id: 'a' }));
typeError(() => applyCatalogCommand({ entries: [{ id: 'a', title: 'A', quantity: 1 }, { id: 'a', title: 'B', quantity: 2 }] }, { type: 'REMOVE', actor: editor, id: 'a' }));
typeError(() => applyCatalogCommand(initial, { type: 'ADD', actor: { id: 'x', role: 'admin' }, entry: { id: 'a', title: 'A', quantity: 1 } }));
typeError(() => applyCatalogCommand(initial, { type: 'ADD', actor: { id: 'x', role: 'editor', extra: 1 }, entry: { id: 'a', title: 'A', quantity: 1 } }));
typeError(() => applyCatalogCommand(initial, { type: 'ADD', actor: editor, entry: { id: '', title: 'A', quantity: 1 } }));
typeError(() => applyCatalogCommand(initial, { type: 'ADD', actor: editor, entry: { id: 'a', title: 'A', quantity: -1 } }));
typeError(() => applyCatalogCommand(changed, { type: 'CHANGE', actor: editor, id: 'a', changes: {} }));
typeError(() => applyCatalogCommand(changed, { type: 'CHANGE', actor: editor, id: 'a', changes: { quantity: 1.5 } }));
typeError(() => applyCatalogCommand(changed, { type: 'REMOVE', actor: editor, id: 'a', extra: 1 }));

